// Generated by Claude for demonstration purposes on this branch.

#include "../../screen_capture.hpp"

#include <windows.h>

#include <chrono>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

namespace {
// Spawns ffmpeg and streams tightly-packed BGRA frames into its stdin.
// ffmpeg finalizes the mp4 when stdin is closed (Finish / destructor).
class FfmpegEncoder {
public:
    FfmpegEncoder() = default;
    FfmpegEncoder(const FfmpegEncoder&) = delete;
    FfmpegEncoder& operator=(const FfmpegEncoder&) = delete;
    ~FfmpegEncoder() { Finish(); }

    // width/height must be even (yuv420p) and constant for the whole recording.
    bool Start(const std::wstring& outputPath, int width, int height, int fps) {
        if (m_process || width <= 0 || height <= 0 || (width % 2) || (height % 2))
            return false;
        m_frameBytes = static_cast<size_t>(width) * height * 4;

        // Pipe whose read end becomes ffmpeg's stdin.
        SECURITY_ATTRIBUTES sa{ sizeof(sa), nullptr, TRUE };
        HANDLE readPipe = nullptr, writePipe = nullptr;
        if (!CreatePipe(&readPipe, &writePipe, &sa, 0)) return false;
        // Our write end must NOT be inherited, or ffmpeg never sees EOF.
        SetHandleInformation(writePipe, HANDLE_FLAG_INHERIT, 0);

        std::wstring cmd =
            L"ffmpeg -y -loglevel error"
            L" -f rawvideo -pixel_format bgra"
            L" -video_size " + std::to_wstring(width) + L"x" + std::to_wstring(height) +
            L" -framerate " + std::to_wstring(fps) +
            L" -i -"
            L" -c:v libx264 -preset veryfast -crf 23 -pix_fmt yuv420p"
            L" -movflags +faststart"
            L" \"" + outputPath + L"\"";

        STARTUPINFOW si{};
        si.cb = sizeof(si);
        si.dwFlags = STARTF_USESTDHANDLES;
        si.hStdInput = readPipe;
        si.hStdOutput = GetStdHandle(STD_OUTPUT_HANDLE);
        si.hStdError = GetStdHandle(STD_ERROR_HANDLE);

        PROCESS_INFORMATION pi{};
        BOOL ok = CreateProcessW(nullptr, cmd.data(), nullptr, nullptr,
                                 TRUE /* inherit handles */, 0,
                                 nullptr, nullptr, &si, &pi);
        CloseHandle(readPipe);  // the child has its own copy now
        if (!ok) {
            CloseHandle(writePipe);
            return false;
        }
        CloseHandle(pi.hThread);
        m_process = pi.hProcess;
        m_stdinWrite = writePipe;
        return true;
    }

    // data must hold exactly width * height * 4 bytes (no row padding).
    bool WriteFrame(const uint8_t* data) {
        if (!m_stdinWrite) return false;
        size_t remaining = m_frameBytes;
        while (remaining > 0) {
            DWORD chunk = remaining > 0x100000 ? 0x100000 : static_cast<DWORD>(remaining);
            DWORD written = 0;
            if (!WriteFile(m_stdinWrite, data, chunk, &written, nullptr) || written == 0)
                return false;  // ffmpeg exited or the pipe broke
            data += written;
            remaining -= written;
        }
        return true;
    }

    // Closes stdin so ffmpeg can finalize the mp4, then waits for it to exit.
    void Finish() {
        if (m_stdinWrite) {
            CloseHandle(m_stdinWrite);
            m_stdinWrite = nullptr;
        }
        if (m_process) {
            WaitForSingleObject(m_process, 30000);
            CloseHandle(m_process);
            m_process = nullptr;
        }
    }

private:
    HANDLE m_stdinWrite = nullptr;
    HANDLE m_process = nullptr;
    size_t m_frameBytes = 0;
};

}  // namespace

int main() {
    winrt::init_apartment(winrt::apartment_type::multi_threaded);

    if (!ScreenCapture::IsSupported()) {
        std::cerr << "Windows.Graphics.Capture not supported.\n";
        return 1;
    }

    constexpr int kFps = 30;
    constexpr int kSeconds = 5;

    // State shared between the capture thread (callback) and main thread.
    // Declared BEFORE `capture` so it outlives any in-flight callback.
    std::mutex mtx;
    std::vector<uint8_t> latest;  // newest frame, tightly packed BGRA, even dimensions
    int encW = 0, encH = 0;
    bool haveFrame = false;
    bool stopped = false;
    Microsoft::WRL::ComPtr<ID3D11DeviceContext> context;
    Microsoft::WRL::ComPtr<ID3D11Texture2D> staging;
    D3D11_TEXTURE2D_DESC stagingDesc{};

    ScreenCapture capture;
    HMONITOR monitor = MonitorFromPoint({ 0, 0 }, MONITOR_DEFAULTTOPRIMARY);

    // The callback only keeps the NEWEST frame on the CPU. Writing to ffmpeg
    // happens on the main thread at a fixed rate (see below).
    bool started = capture.Start(monitor, [&](ID3D11Texture2D* tex, int, int, int64_t) {
        std::lock_guard<std::mutex> lock(mtx);
        if (stopped) return;

        D3D11_TEXTURE2D_DESC desc;
        tex->GetDesc(&desc);

        // (Re)create the CPU-readable staging texture when needed.
        if (!staging || desc.Width != stagingDesc.Width || desc.Height != stagingDesc.Height) {
            Microsoft::WRL::ComPtr<ID3D11Device> device;
            tex->GetDevice(&device);
            device->GetImmediateContext(&context);

            D3D11_TEXTURE2D_DESC sd = desc;
            sd.Usage = D3D11_USAGE_STAGING;
            sd.BindFlags = 0;
            sd.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
            sd.MiscFlags = 0;
            staging.Reset();
            if (FAILED(device->CreateTexture2D(&sd, nullptr, &staging))) return;
            stagingDesc = desc;
        }

        // yuv420p needs even dimensions: drop a trailing odd row/column if present.
        const int w = static_cast<int>(desc.Width & ~1u);
        const int h = static_cast<int>(desc.Height & ~1u);
        // The encoder's size is fixed once recording starts, so skip frames of another size.
        if (haveFrame && (w != encW || h != encH)) return;

        context->CopyResource(staging.Get(), tex);
        D3D11_MAPPED_SUBRESOURCE mapped;
        if (FAILED(context->Map(staging.Get(), 0, D3D11_MAP_READ, 0, &mapped))) return;

        encW = w;
        encH = h;
        const size_t rowBytes = static_cast<size_t>(w) * 4;
        latest.resize(rowBytes * h);
        for (int y = 0; y < h; ++y) {
            std::memcpy(latest.data() + y * rowBytes,
                        static_cast<const uint8_t*>(mapped.pData) + static_cast<size_t>(y) * mapped.RowPitch,
                        rowBytes);
        }
        context->Unmap(staging.Get(), 0);
        haveFrame = true;
    });

    if (!started) {
        std::cerr << "Failed to start capture.\n";
        return 1;
    }

    // Wait for the first frame so we know the video size.
    // (Capture only delivers frames when the screen changes: move the mouse if this stalls.)
    const auto waitStart = std::chrono::steady_clock::now();
    while (true) {
        {
            std::lock_guard<std::mutex> lock(mtx);
            if (haveFrame) break;
        }
        if (std::chrono::steady_clock::now() - waitStart > std::chrono::seconds(5)) {
            std::cerr << "No frames received.\n";
            capture.Stop();
            return 1;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    int width = 0, height = 0;
    {
        std::lock_guard<std::mutex> lock(mtx);
        width = encW;
        height = encH;
    }

    FfmpegEncoder encoder;
    if (!encoder.Start(L"capture.mp4", width, height, kFps)) {
        std::cerr << "Failed to start ffmpeg (is it on PATH?).\n";
        capture.Stop();
        return 1;
    }
    std::cout << "Recording " << width << "x" << height << " @ " << kFps
              << " fps for " << kSeconds << "s...\n";

    // Write the newest frame at a constant rate. Capture only delivers frames when the
    // screen changes, but ffmpeg expects exactly kFps frames per second, so we repeat
    // the latest frame as needed. Without this, a static screen would produce a video
    // that plays back far too fast.
    std::vector<uint8_t> out;
    const auto interval = std::chrono::duration_cast<std::chrono::steady_clock::duration>(
        std::chrono::duration<double>(1.0 / kFps));
    auto next = std::chrono::steady_clock::now();
    for (int i = 0; i < kFps * kSeconds; ++i) {
        next += interval;
        std::this_thread::sleep_until(next);
        {
            std::lock_guard<std::mutex> lock(mtx);
            out = latest;  // copy under the lock, write outside it
        }
        if (!encoder.WriteFrame(out.data())) {
            std::cerr << "Write to ffmpeg failed.\n";
            break;
        }
    }

    // Shut down: stop the callback from touching anything, stop capture, finalize the mp4.
    {
        std::lock_guard<std::mutex> lock(mtx);
        stopped = true;
    }
    capture.Stop();
    encoder.Finish();

    std::cout << "Done: capture.mp4\n";
    return 0;
}